// ETIQUETAS DOS NIVEIS , no site atual cada nivel-chave aparece marcado NA
            // BARRA (Call Wall, Zero Gamma, Vol Trigger, Max Pain, Put Wall, HVL) e o
            // strike correspondente vira pilula colorida. Sem isso o grafico e so um
            // monte de barra sem referencia.
            var NIV = [
              { v: x.call_wall,   t: 'Call Wall',   c: '#f87171' },
              { v: x.zero_gamma,  t: 'Zero Gamma',  c: '#fbbf24' },
              { v: x.vol_trigger, t: 'Vol Trigger', c: '#fb923c' },
              { v: x.max_pain,    t: 'Max Pain',    c: '#a78bfa' },
              { v: x.put_wall,    t: 'Put Wall',    c: '#34d399' },
              { v: x.hvl,         t: 'HVL',         c: '#22d3ee' }
            ].filter(function (n) { return Number(n.v) > 0; });
            var BASE_S = 'width:52px;flex-shrink:0;text-align:right;font-size:10.5px;font-variant-numeric:tabular-nums;';
            var bars = ts.map(function (s) {
              var call = (Number(s.gex) || 0) >= 0;
              var w = Math.max(6, Math.round(Math.abs(Number(s.gex) || 0) / maior * 100));
              var st = Number(s.strike);
              var hit = null;
              for (var q = 0; q < NIV.length; q++) { if (Math.round(Number(NIV[q].v)) === Math.round(st)) { hit = NIV[q]; break; } }
              return { strike: st.toLocaleString('en-US'),
                strikeStyle: hit
                  ? (BASE_S + 'padding:1px 6px;border-radius:5px;font-weight:800;color:#0a0d07;background:' + hit.c + ';')
                  : (BASE_S + 'color:#8a94a0;'),
                tag: hit ? hit.t : '',
                tagStyle: hit
                  ? ('flex-shrink:0;font-size:10px;font-weight:800;padding:2px 8px;border-radius:6px;color:#0a0d07;background:' + hit.c + ';')
                  : 'flex-shrink:0;width:0;',
                justify: call ? 'justify-content:flex-start' : 'justify-content:flex-end',
                barStyle: 'height:11px;border-radius:3px;width:' + w + '%;background:' + (call ? '#34d399' : '#f87171') + ';' };
            });
